fn acquire_combiner_lock(&self) -> (result: (bool, Tracked<Option<CombinerLockStateGhost<DT>>>))
    requires
        self.wf(),
    ensures
        result.0 ==> result.1@.is_some(),
        result.0 ==> result.1@.unwrap().inv(
